-- JL Trainer Armadura: execute this file once in Supabase SQL Editor.
create extension if not exists pgcrypto;
do $$ begin create type public.app_role as enum ('client','coach','admin'); exception when duplicate_object then null; end $$;
do $$ begin create type public.subscription_status as enum ('pending','active','expired','suspended'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default 'Cliente', email text, phone text, city text, role app_role not null default 'client', height numeric, initial_weight numeric, current_weight numeric, goal text, modality text, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.plans (id uuid primary key default gen_random_uuid(), name text unique not null, price numeric not null check(price>=0), currency text not null default 'MZN', description text, features jsonb not null default '[]', tier int not null default 0, active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, plan_id uuid not null references public.plans(id), status subscription_status not null default 'pending', started_at date, expires_at date, payment_status text not null default 'pending', payment_reference text, created_at timestamptz not null default now());
create table if not exists public.payments (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, plan_id uuid references public.plans(id), amount numeric, currency text default 'MZN', method text, status text not null default 'pending', reference text, proof_path text, confirmed_at timestamptz, confirmed_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table if not exists public.modalities (id uuid primary key default gen_random_uuid(), name text unique not null, description text, image_path text, active boolean default true, sort_order int default 0);
create table if not exists public.exercises (id uuid primary key default gen_random_uuid(), name text not null, category text, description text, muscle_group text, sets int default 3, reps text default '8–12', rest_seconds int default 60, equipment text default 'Sem equipamento', min_tier int default 0, image_path text, video_path text);
create table if not exists public.workouts (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) on delete cascade, modality_id uuid references public.modalities(id), title text not null, description text, min_tier int default 0, active boolean default true, created_at timestamptz default now());
create table if not exists public.workout_exercises (id uuid primary key default gen_random_uuid(), workout_id uuid references public.workouts(id) on delete cascade, exercise_id uuid references public.exercises(id) on delete cascade, sort_order int default 0);
create table if not exists public.training_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, workout_id uuid references public.workouts(id), workout_name text, completed_at timestamptz not null default now(), notes text, loads jsonb default '{}');
create table if not exists public.progress_measurements (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, measured_at date not null default current_date, weight numeric check(weight>0 and weight<500), arm numeric, chest numeric, waist numeric, hip numeric, thigh numeric, body_fat numeric, notes text, created_at timestamptz default now());
create table if not exists public.progress_photos (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, path text not null, note text, created_at timestamptz default now());
create table if not exists public.content (id uuid primary key default gen_random_uuid(), title text not null, description text, type text not null check(type in ('video','image','document','text')), bucket text, path text, min_plan uuid references public.plans(id), published boolean default false, created_at timestamptz default now());
create table if not exists public.calendar_events (id uuid primary key default gen_random_uuid(), title text not null, description text, kind text default 'workout', starts_at timestamptz not null, duration_minutes int default 60, meeting_url text, created_at timestamptz default now());
create table if not exists public.mentorship_bookings (id uuid primary key default gen_random_uuid(), event_id uuid references public.calendar_events(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, created_at timestamptz default now(), unique(event_id,user_id));
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) on delete cascade, title text not null, message text not null, read boolean default false, created_at timestamptz default now());
create table if not exists public.messages (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) on delete cascade, role text not null check(role in ('user','assistant')), body text not null, created_at timestamptz default now());
create table if not exists public.settings (id text primary key, name text default 'JL TRAINER ARMADURA', whatsapp text default '258868787572', coach_name text default 'Seu coach', coach_bio text, vip_link text);
create table if not exists public.account_requests (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) on delete cascade, type text, status text default 'pending', created_at timestamptz default now());
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role in ('coach','admin')); $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,email) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','Cliente'),new.email) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into public.plans(name,price,tier,description,features) values ('GRÁTIS',0,0,'Acesso inicial','["3 exercícios introdutórios","Registro de peso"]'),('START',600,1,'Para começar','["Treinos completos","Imagens","Assistente guiado"]'),('PRO',1200,2,'Evolução acompanhada','["Tudo do START","Videoaulas","2 mentorias"]'),('PREMIUM',1800,3,'Acompanhamento completo','["Tudo do PRO","Treino personalizado","Suporte prioritário"]') on conflict(name) do update set price=excluded.price,tier=excluded.tier,features=excluded.features;
insert into public.modalities(name,description,sort_order) values ('Musculação','Força com técnica e consistência',1),('Ganho de massa','Progressão gradual de cargas',2),('Bulking','Construa sua base de força',3),('Definição','Treino e hábitos sustentáveis',4),('Emagrecimento','Movimento para sua rotina',5),('Treino em casa','Com ou sem equipamento',6),('Karatê','Base, kihon, kata e mobilidade',7),('Futsal','Passe, agilidade e condicionamento',8),('Natação','Respiração e técnica na água',9) on conflict(name) do nothing;
insert into public.settings(id) values('platform') on conflict(id) do nothing;
-- RLS: clients can only read/write their own records. Plan metadata and modalities are readable.

do $$ declare t text; begin foreach t in array array['profiles','subscriptions','payments','workouts','workout_exercises','training_logs','progress_measurements','progress_photos','notifications','messages','mentorship_bookings','account_requests'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
alter table public.plans enable row level security; alter table public.modalities enable row level security; alter table public.exercises enable row level security; alter table public.content enable row level security; alter table public.calendar_events enable row level security; alter table public.settings enable row level security;
create policy profiles_select on public.profiles for select using(id=auth.uid() or public.is_staff()); create policy profiles_insert on public.profiles for insert with check(id=auth.uid()); create policy profiles_update on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy own_subscriptions on public.subscriptions for select using(user_id=auth.uid() or public.is_staff()); create policy own_payments on public.payments for select using(user_id=auth.uid() or public.is_staff()); create policy payment_insert on public.payments for insert with check(user_id=auth.uid());
create policy plans_read on public.plans for select using(active=true or public.is_staff()); create policy modalities_read on public.modalities for select using(active=true or public.is_staff()); create policy exercises_read on public.exercises for select using(true); create policy events_read on public.calendar_events for select using(true); create policy settings_read on public.settings for select using(true);
create policy workout_read on public.workouts for select using(user_id=auth.uid() or user_id is null or public.is_staff()); create policy workout_exercise_read on public.workout_exercises for select using(exists(select 1 from public.workouts w where w.id=workout_id and (w.user_id=auth.uid() or w.user_id is null or public.is_staff())));
create policy own_logs on public.training_logs for all using(user_id=auth.uid() or public.is_staff()) with check(user_id=auth.uid() or public.is_staff()); create policy own_measurements on public.progress_measurements for all using(user_id=auth.uid() or public.is_staff()) with check(user_id=auth.uid() or public.is_staff()); create policy own_photos on public.progress_photos for all using(user_id=auth.uid() or public.is_staff()) with check(user_id=auth.uid() or public.is_staff()); create policy content_read on public.content for select using(published=true or public.is_staff()); create policy own_notifications on public.notifications for select using(user_id=auth.uid() or public.is_staff()); create policy own_messages on public.messages for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy booking_own on public.mentorship_bookings for all using(user_id=auth.uid() or public.is_staff()) with check(user_id=auth.uid() or public.is_staff()); create policy request_own on public.account_requests for insert with check(user_id=auth.uid());
create or replace function public.admin_activate_subscription(p_user_id uuid,p_plan_id uuid,p_expires_at date,p_reference text default null) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() then raise exception 'admin_required'; end if; update subscriptions set status='suspended' where user_id=p_user_id and status='active'; insert into subscriptions(user_id,plan_id,status,started_at,expires_at,payment_status,payment_reference) values(p_user_id,p_plan_id,'active',current_date,p_expires_at,'confirmed',p_reference); end; $$;
create or replace function public.admin_confirm_payment(payment_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare p payments; begin if not public.is_admin() then raise exception 'admin_required'; end if; select * into p from payments where id=payment_id; update payments set status='confirmed',confirmed_at=now(),confirmed_by=auth.uid() where id=payment_id; end; $$;
create or replace function public.book_mentorship(event uuid) returns void language plpgsql security definer set search_path=public as $$ declare tier int; begin select coalesce(max(pl.tier),0) into tier from subscriptions s join plans pl on pl.id=s.plan_id where s.user_id=auth.uid() and s.status='active' and s.expires_at>=current_date; if tier<2 then raise exception 'pro_required'; end if; insert into mentorship_bookings(event_id,user_id) values(event,auth.uid()); end; $$;
create or replace function public.guided_chat(question text) returns void language plpgsql security definer set search_path=public as $$ begin insert into messages(user_id,role,body) values(auth.uid(),'user',left(question,1000)),(auth.uid(),'assistant',case when lower(question) like '%treino%' then 'Consulte a aba Treinos para iniciar seu programa de hoje.' when lower(question) like '%progresso%' then 'Registre uma medida na aba Progresso para acompanhar sua evolução.' else 'Mantenha a técnica, respeite o descanso e procure seu coach para orientações personalizadas.' end); end; $$;
-- Storage buckets and object policies
insert into storage.buckets(id,name,public) values('videos','videos',false),('images','images',false),('documents','documents',false),('profile-photos','profile-photos',false),('progress-photos','progress-photos',false),('payment-proofs','payment-proofs',false) on conflict(id) do nothing;
create policy private_read_own on storage.objects for select using(bucket_id in ('progress-photos','profile-photos','payment-proofs') and (auth.uid()::text=(storage.foldername(name))[1] or public.is_staff())); create policy private_insert_own on storage.objects for insert with check(bucket_id in ('progress-photos','profile-photos','payment-proofs') and auth.uid()::text=(storage.foldername(name))[1]); create policy staff_content_upload on storage.objects for insert with check(bucket_id in ('videos','images','documents') and public.is_staff()); create policy staff_content_read on storage.objects for select using(bucket_id in ('videos','images','documents') and public.is_staff());
